// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        vm.prank(address(this));
        c.initialize();

        address programOperator = address(0x123);
        vm.prank(address(this));
        c.programOperators(programOperator);
        address dummyRound = address(new RoundDummy());
        vm.prank(address(this));
        c.updateRoundImplementation(payable(dummyRound));

        vm.prank(address(this));
        c.updateAlloSettings(address(0x1));

        address actualOwner = c.owner();
        assertTrue(actualOwner == address(this), "Owner mismatch");
    }
}

contract RoundDummy {
    function initialize(bytes calldata, address) external {}
}
